entries[80719] = { ["name"] = "Fläschchen der Stahlhaut", ["text"] = "Wirken in 2.5 sek.\nReagenzien:\nFlüchtiges Leben (8), Aschenblüte (8), Schattenjasmin (8), Kristallphiole\nBerufsausbilder:\nAlchemie des Kataklysmus (50)\nKosten:\n2\n\nBenutzen: Erhöht die Ausdauer 1 Stunde lang um 24 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n30" }
entries[80720] = { ["name"] = "Fläschchen der drakonischen Gedanken", ["text"] = "Wirken in 2.5 sek.\nReagenzien:\nFlüchtiges Leben (8), Azsharas Schleier (8), Schattenjasmin (8), Kristallphiole\nBerufsausbilder:\nAlchemie des Kataklysmus (55)\nKosten:\n2\n25\n\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 16 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n30" }
entries[80721] = { ["name"] = "Fläschchen der Winde", ["text"] = "Wirken in 2.5 sek.\nReagenzien:\nFlüchtiges Leben (8), Azsharas Schleier (8), Gertenrohr (8), Kristallphiole\nBerufsausbilder:\nAlchemie des Kataklysmus (60)\nKosten:\n2\n50\n\nBenutzen: Erhöht die Beweglichkeit 1 Stunde lang um 16 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\n30" }
