entries[80726] = { ["name"] = "Trank des Schätzefindens", ["text"] = "Wirken in 2 sek.\nReagenzien:\nAschenblüte (8), Sturmwinde (4), Herzblüte (6), Gertenrohr (4), Kristallphiole\nBerufsausbilder:\nAlchemie des Kataklysmus (75)\nKosten:\n3\n50\n\nBenutzen: Gestattet es Euch, manchmal zusätzliche Beute von Monstern auf dem Hyjal, in Vashj'ir, in Tiefenheim, im Schattenhochland und in Uldum zu bekommen. Hält 1 Stunde lang an. Dieser Effekt hält über den Tod hinaus an. (5 Min Abklingzeit)\n30" }
